<?php

namespace App\Support;

use App\Enums\JourneyContentType;
use App\Enums\JourneyStep;
use App\Models\AIProposal;
use App\Models\UsageEvent;
use Illuminate\Support\Str;

/**
 * Records creation-journey steps (ClickUp 86e3qkxtc) as usage_events rows.
 *
 * A journey is identified by (user, journey_id): the id is generated by the
 * browser when a create form opens, or server-side for an AI proposal that
 * arrives without one. Reads always group by user AND journey_id, so a
 * journey id guessed from someone else can never merge into their journey.
 *
 * Rows carry ids and step names only — never form content, prompts, AI
 * responses, raw errors or student data (CLAUDE.md rules 2 and 11).
 */
class UsageJourney
{
    /**
     * The journey a model created right now belongs to; read by
     * LogsUsageEvents so the `*.created` row doubles as the journey's
     * `creation_confirmed` step.
     */
    protected static ?string $current = null;

    /**
     * Run $callback with $journeyId as the current journey (null runs it
     * outside any journey), always restoring the previous one.
     *
     * @template T
     *
     * @param  callable(): T  $callback
     * @return T
     */
    public static function within(?string $journeyId, callable $callback): mixed
    {
        $previous = static::$current;
        static::$current = $journeyId;

        try {
            return $callback();
        } finally {
            static::$current = $previous;
        }
    }

    public static function current(): ?string
    {
        return static::$current;
    }

    /**
     * @param  array<string, scalar|null>  $metadata  ids/categories only
     */
    public static function record(
        int $userId,
        string $journeyId,
        JourneyStep $step,
        JourneyContentType|string $contentType,
        ?int $groupId = null,
        ?int $contentId = null,
        array $metadata = [],
    ): UsageEvent {
        return UsageEvent::create([
            'user_id' => $userId,
            'event_type' => $step->eventType(),
            'journey_id' => $journeyId,
            'step' => $step->value,
            'content_type' => $contentType instanceof JourneyContentType ? $contentType->value : $contentType,
            'content_id' => $contentId,
            'group_id' => $groupId,
            'metadata' => $metadata === [] ? null : $metadata,
        ]);
    }

    /**
     * Record a generation request for $proposal: the journey's single
     * attempt the first time, a retry/change request afterwards.
     */
    public static function recordGenerationRequest(AIProposal $proposal): void
    {
        $alreadyRequested = UsageEvent::query()
            ->where('user_id', $proposal->requested_by_id)
            ->where('journey_id', $proposal->journey_id)
            ->whereIn('step', [JourneyStep::GenerationRequested->value, JourneyStep::RegenerationRequested->value])
            ->exists();

        static::record(
            $proposal->requested_by_id,
            $proposal->journey_id,
            $alreadyRequested ? JourneyStep::RegenerationRequested : JourneyStep::GenerationRequested,
            $proposal->type->value,
            $proposal->group_id,
            metadata: ['ai_proposal_id' => $proposal->id],
        );
    }

    /**
     * The journey a new AI proposal belongs to: the one the browser sent, or
     * the referenced proposal's (a change request on an earlier draft of the
     * same teacher), or a fresh one.
     */
    public static function forNewProposal(?string $journeyId, ?AIProposal $reference, int $userId): string
    {
        if ($journeyId !== null) {
            return $journeyId;
        }

        if ($reference !== null && $reference->requested_by_id === $userId && $reference->journey_id !== null) {
            return $reference->journey_id;
        }

        return (string) Str::uuid();
    }
}
